// HA StatusFrame V2 – physical LED numbers 1..30, array index = LED number - 1
// N=off, NP=pulsing green, A=solid red, AB=blinking red, H=pulsing blue
const now=Date.now();
const val=k=>flow.get(k);
const valid=v=>v!==undefined && v!==null && !["unknown","unavailable",""].includes(String(v).toLowerCase());
const isHome=k=>val(k)==="home";
const isOn=k=>val(k)==="on";
const leds=Array(30).fill("N");
// 1–5: existing status monitors
leds[0]=flow.get("internet_ok")===true ? "N":"AB";
leds[1]=flow.get("hms_ok")===true ? "N":"AB";
leds[2]=flow.get("opendtu_ok")===true ? "N":"AB";
leds[3]=flow.get("victron_ok")===true ? "N":"AB";
leds[4]=(val("ccu3_hmip_state")==="on" && val("ccu3_virtual_state")==="on") ? "N":"AB";
// 6 Sungrow network
leds[5]=isHome("sungrow_reachable") ? "N":"AB";
// 7 Heat pump: bus / EMS / compressor alarm / compressor running
const wpError=val("wp_system")!=="on" || val("wp_bus")!=="connected" || !valid(val("wp_activity")) || !["on","off"].includes(String(val("wp_compressor"))) || val("wp_activity")==="compressor alarm";
leds[6]=wpError ? "AB" : isOn("wp_compressor") ? "NP":"N";
// 8 Wallbox OCPP and hourly heartbeat (90-minute tolerance)
const wbState=val("wallbox_status");
const hb=val("wallbox_heartbeat");
let hbTime=NaN;
if (valid(hb)) {
  const n=Number(hb);
  hbTime=Number.isFinite(n) && String(hb).trim()!=="" ? (n>1e12?n:n>1e9?n*1000:NaN) : Date.parse(String(hb));
}
const wbError=!valid(wbState) || wbState==="Faulted" || !Number.isFinite(hbTime) || hbTime>now+60000 || now-hbTime>90*60000;
leds[7]=wbError ? "AB" : wbState==="Charging" ? "NP":"N";
// 9 ESP devices continuously connected to the network
leds[8]=["esp_heizung","esp_hoymiles","esp_sungrow","esp_treppe"].every(isHome) ? "N":"AB";
// 10 Samba backup
leds[9]=flow.get("backup_ok")===true ? "N":"AB";
// 11 Victron float or absorption
leds[10]=(flow.get("pv_absorption")===true || flow.get("pv_float")===true) ? "AB":"N";
// 12 unused; 13 Hoymiles production; 14/15 unused
leds[12]=flow.get("hms_producing")===true ? "NP":"N";
// Battery status: 11 CCU3 binary sensors, 7 percentage values.
// Treat unknown values as data errors only after 5 minutes.
const batteryBinary = ["buero_wand_ok", "bad_wand_ok", "flur_wand_ok", "wohnzimmer_wand_ok", "schlafzimmer_wand_ok", "handtuchheizung_ok", "atelierheizung_ok", "schlafzimmerheizung_ok", "bad_fenster_homematic_ok", "atelier_fenster_homematic_ok", "schlafzimmer_fenster_homematic_ok"];
const batteryPercent = ["pv_akku_ok", "fenster_bad_shelly_ok", "fahrradschuppen_shelly_ok", "atelier_switchbot_ok", "hauswirtschaft_ok", "schweinestall_switchbot_ok", "haustuer_switchbot_ok"];

let batteryWarnings = [], batteryAlarms = [], batteryMissing = [];
for (const [key, isBinary] of [...batteryBinary.map(k => [k,true]), ...batteryPercent.map(k => [k,false])]) {
  const raw = flow.get("battery_raw_" + key);
  const valid = isBinary ? (raw === "on" || raw === "off") : (raw !== undefined && raw !== null && String(raw).trim() !== "" && Number.isFinite(Number(raw)));
  if (valid) {
    flow.set("battery_missing_since_" + key, null);
    if (isBinary && raw === "on") batteryAlarms.push(key);
    if (!isBinary) {
      const value = Number(raw);
      if (value <= 20) batteryAlarms.push(key + "=" + value + "%");
      else if (value <= 40) batteryWarnings.push(key + "=" + value + "%");
    }
  } else {
    let since = flow.get("battery_missing_since_" + key);
    if (!since) { since = now; flow.set("battery_missing_since_" + key, since); }
    if (now - since >= 300000) batteryMissing.push(key);
  }
}
// Alarm takes priority over data errors, followed by warnings.
const battery_token = batteryAlarms.length ? "A" : batteryMissing.length ? "AB" : batteryWarnings.length ? "H" : "N";
const battery_diagnose = {alarm:batteryAlarms, warnung:batteryWarnings, nicht_verfuegbar:batteryMissing};
flow.set("battery_diagnose", battery_diagnose);
// Diagnostics only in flow context; no continuous warning logging
node.status({fill:battery_token === "N" ? "green" : battery_token === "H" ? "blue" : "red",shape:"dot",text:"Batterie " + battery_token + " | A:"+batteryAlarms.length+" W:"+batteryWarnings.length+" X:"+batteryMissing.length});

leds[15]=battery_token;
// 17/18 simple power detection (separate function nodes)
leds[16]=flow.get("trockner_token") || "N";
leds[17]=flow.get("waschmaschine_token") || "N";
// 19/20: grid import >200W / export >500W, each for 5 minutes
const raw=val("meter_power");
const p=valid(raw) && String(raw).trim()!=="" ? Number(raw):NaN;
function timedLimit(key,condition) {
 if (!condition) {flow.set(key,null);return false;}
 let since=flow.get(key);
 if (!since) {since=now;flow.set(key,since);}
 return now-since>=300000;
}
leds[18]=timedLimit("grid_import_since",Number.isFinite(p) && p>200) ? "AB":"N";
leds[19]=timedLimit("grid_export_since",Number.isFinite(p) && p< -500) ? "AB":"N";
// 21 All shutters closed at night
const night=val("sun_state")==="below_horizon";
const shuttersClosed=flow.get("rolladen_buero_ok")===true && flow.get("rolladen_kueche_ok")===true && val("rolladen_wohnzimmer")==="closed";
leds[20]=!valid(val("sun_state")) || (night && !shuttersClosed) ? "AB":"N";
// 22 Windows: open = A, missing data = AB
const win=["fenster_bad_ok","fenster_schlafzimmer_ok","fenster_atelier_ok"].map(val);
leds[21]=win.some(v=>v===false) ? "A" : win.every(v=>v===true) ? "N":"AB";
// 23 Outdoor lighting: at least one light on
const lights=["giebel_ok","strasse_ok","terasse_ok"].map(val);
leds[22]=lights.every(v=>v===true) ? "N":"AB";
// 24 Driveway: nighttime motion from camera or motion sensor
const drivewayMotion=val("reolink_ok")===false || val("einfahrt_bm_ok")===false;
leds[23]=night && drivewayMotion ? "AB":"N";
// 25 Fountain switched on
leds[24]=val("brunnen_ok")===true ? "N":"AB";
// 26 unused
// 27 Frost: <=1°C and humidity >70%
const t=Number(val("aussen_temp"));const h=Number(val("aussen_luftfeuchte"));
leds[26]=valid(val("aussen_temp")) && valid(val("aussen_luftfeuchte")) && Number.isFinite(t) && Number.isFinite(h) && t<=1 && h>70 ? "AB":"N";
// 28/29 Commute routes
leds[27]=Number(val("pendelstrecke_person_1"))>35 ? "AB":"N";
leds[28]=Number(val("pendelstrecke_person_2"))>40 ? "AB":"N";
// 30 unused
msg.topic="stoermeldeboard/states";
msg.payload=JSON.stringify(leds);
return msg;

const cfg = {
    version: 1,

    layout: {
        cols: 3,
        rows: 10,
        serpentine: true,
