    },

    global: {
        master_brightness: 60,  // 0..255
        timeout_ms: 15000,
        fallback_token: "A"      // on failure, show solid red on all LEDs
    },

    tokens: {
        // N = normal (LED off)
        N: { rgb: [0, 0, 0], mode: "static", brightness: 0 },

        // NP = pulsing green
        NP: { rgb: [0, 255, 0], mode: "pulse", brightness: 255, pulse_ms: 1400, pulse_min: 20 },

        // A = solid red
        A: { rgb: [255, 0, 0], mode: "static", brightness: 255 },

        // AB = blinking red
        AB: { rgb: [255, 0, 0], mode: "blink", brightness: 255, blink_ms: 250, duty: 0.5 },

        // H = informational status (pulsing blue)
        H: { rgb: [0, 0, 255], mode: "pulse", brightness: 255 }
    }
};

msg.topic = "stoermeldeboard/config";
msg.payload = JSON.stringify(cfg);
return msg;

