// If empty/unknown/unavailable -> FAIL
if (!state || state === "unknown" || state === "unavailable") {
  flow.set("backup_ok", false);
  node.warn(`Backup timestamp invalid state: ${state}`);
  return msg;
}

// "YYYY-MM-DD HH:MM:SS" -> "YYYY-MM-DDTHH:MM:SS"
const iso = state.replace(" ", "T");

// Timestamp in milliseconds
const backupMs = Date.parse(iso);
const nowMs = Date.now();

if (isNaN(backupMs)) {
  flow.set("backup_ok", false);
  node.warn(`Backup timestamp parse failed: ${state} -> ${iso}`);
  return msg;
}

const diffDays = (nowMs - backupMs) / (1000 * 60 * 60 * 24);
const ok = diffDays <= 7;

flow.set("backup_ok", ok);
node.warn(`Backup age: ${diffDays.toFixed(2)} days -> backup_ok=${ok}`);

return msg;

// dryer token: above 10 W = NP, below 10 W for 5 minutes = N.
// Event payload is entityState as a string; ticker is a numeric timestamp.
const incoming=msg.payload;
const event=typeof incoming==="string" ? incoming : (incoming && typeof incoming==="object" ? incoming.state : undefined);
if (event!==undefined) {
 const p=Number(event);
 if (String(event).trim()!=="" && Number.isFinite(p)) flow.set("trockner_power_v2",p);
}
const p=flow.get("trockner_power_v2");
const now=Date.now();
let active=flow.get("trockner_running_v2")===true;
let below=flow.get("trockner_below_since_v2") || 0;
if (typeof p==="number" && Number.isFinite(p)) {
 if (p>10) {active=true;below=0;}
 else if (active) {
  if (!below) below=now;
  if (now-below>=5*60000) {active=false;below=0;}
 } else below=0;
}
flow.set("trockner_running_v2",active);
flow.set("trockner_below_since_v2",below);
flow.set("trockner_token",active ? "NP":"N");
return msg;

